1	// Blind grading for the forward run (DESIGN.md §"Forward run"): random X/Y labels, a judge that sees only the
2	// labelled diffs, and the merge policy. Randomness is a seeded PRNG so every pick can be replayed from the logged seed.
3	import type { ChatMessage, LlmClient } from "../llm/types.ts";
4	import type { ForwardPair } from "../types.ts";
5	
6	export type Side = "old" | "new";
7	export type Verdict = "X" | "Y" | "tie";
8	
9	/** mulberry32: a small deterministic PRNG, so a logged seed reproduces labels and tie-breaks. */
10	export function rng(seed: number): () => number {
11	  let a = seed >>> 0;
12	  return () => {
13	    a = (a + 0x6d2b79f5) >>> 0;
14	    let t = a;
15	    t = Math.imul(t ^ (t >>> 15), t | 1);
16	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
17	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
18	  };
19	}
20	
21	/** A per-pair seed derived from the run seed and the task id (FNV-1a), stable across resumes. */
22	export function pairSeed(runSeed: number, taskId: string): number {
23	  let h = (0x811c9dc5 ^ runSeed) >>> 0;
24	  for (const ch of taskId) h = Math.imul(h ^ ch.charCodeAt(0), 0x01000193) >>> 0;
25	  return h;
26	}
27	
28	/** Which side is shown as X; the other is Y. */
29	export function assignLabels(random: () => number): Record<"X" | "Y", Side> {
30	  return random() < 0.5 ? { X: "old", Y: "new" } : { X: "new", Y: "old" };
31	}
32	
33	/** Removes anything that names a setup or the branch it ran on, so the judge cannot tell the sides apart. */
34	export function scrub(text: string, hide: string[]): string {
35	  let out = text.replace(/forward\/[\w.-]+\/(old|new)/g, "<branch>");
36	  for (const h of hide.filter((s) => s.length > 0)) out = out.split(h).join("<setup>");
37	  return out;
38	}
39	
40	const SYSTEM = `You compare two candidate changes, X and Y, for the same task. You know nothing about who or what wrote them.
41	Judge correctness against the task, then scope discipline, then simplicity. Reply with one line: "verdict: X", "verdict: Y" or "verdict: tie".`;
42	
43	/** The judge's whole input: the task text and the two labelled diffs, nothing that identifies a setup. */
44	export function blindMessages(task: string, diffX: string, diffY: string, hide: string[] = []): ChatMessage[] {
45	  const body = [
46	    "Task:",
47	    scrub(task, hide),
48	    "",
49	    "=== Change X ===",
50	    scrub(diffX, hide),
51	    "",
52	    "=== Change Y ===",
53	    scrub(diffY, hide),
54	    "",
55	  ].join("\n");
56	  return [
57	    { role: "system", content: SYSTEM },
58	    { role: "user", content: body },
59	  ];
60	}
61	
62	export function parseVerdict(text: string | null): Verdict {
63	  const m = [...(text ?? "").matchAll(/verdict:\s*(X|Y|tie)\b/gi)].at(-1);
64	  if (!m) return "tie";
65	  const v = m[1]!.toUpperCase();
66	  return v === "X" ? "X" : v === "Y" ? "Y" : "tie";
67	}
68	
69	export interface BlindResult {
70	  labels: Record<"X" | "Y", Side>;
71	  verdict: Verdict;
72	  /** The preferred side, or null on a tie. */
73	  preferred: Side | null;
74	  /** The labelled input the judge saw, kept so logs and tests can show it was blind. */
75	  input: ChatMessage[];
76	}
77	
78	/** Labels the two diffs at random, asks the judge, and maps the verdict back to a side. */
79	export async function blindJudge(
80	  llm: LlmClient,
81	  task: string,
82	  diffs: Record<Side, string>,
83	  random: () => number,
84	  hide: string[] = [],
85	): Promise<BlindResult> {
86	  const labels = assignLabels(random);
87	  const input = blindMessages(task, diffs[labels.X], diffs[labels.Y], hide);
