65	/** Test command by project markers: bun, pnpm, npm, pytest, go test. */
66	export function detectTestCmd(dir: string): string {
67	  const has = (f: string) => existsSync(join(dir, f));
68	  if (has("bun.lock") || has("bun.lockb") || has("bunfig.toml")) return "bun test";
69	  if (has("pnpm-lock.yaml")) return "pnpm test";
70	  if (has("package.json")) return "npm test";
71	  if (has("pyproject.toml") || has("pytest.ini") || has("setup.py")) return "pytest";
