91	function junitCases(xml: string): JunitCase[] {
92	  const out: JunitCase[] = [];
93	  const stack: string[] = [];
94	  const tokens = xml.match(/<testsuite\b[^>]*>|<\/testsuite>|<testcase\b[^>]*?\/>|<testcase\b[^>]*>[\s\S]*?<\/testcase>/g) ?? [];
95	  for (const t of tokens) {
96	    if (t.startsWith("</testsuite")) stack.pop();
97	    else if (t.startsWith("<testsuite")) stack.push(attr(t, "file") ?? attr(t, "name") ?? stack.at(-1) ?? "");
98	    else {
99	      const head = t.slice(0, t.indexOf(">") + 1);
