101	      out.push({ file, name: attr(head, "name") ?? "", failed: /<(failure|error)\b/.test(t), skipped: /<skipped\b/.test(t) });
102	    }
103	  }
104	  return out;
105	}
106	
107	/** Per-testcase results from a JUnit file, attributed to the test file of the enclosing suite. */
108	export function parseJunit(xml: string): PerTest[] {
109	  return junitCases(xml).map((c) => ({ file: c.file, name: c.name, pass: !c.failed && !c.skipped }));
110	}
111	
112	/** Test files with at least one failed or errored case (skips don't count), in first-seen order. */
113	export function failingTestFiles(xml: string): string[] {
114	  return [...new Set(junitCases(xml).filter((c) => c.failed).map((c) => c.file.replace(/^\.\//, "")))].filter(Boolean);
115	}
116	
117	// Async on purpose: a spawnSync here froze the whole forward run (every worker, every agent launch) for the length of
118	// each suite run, so "parallel" pairs were graded one step at a time.
119	const sh: StepRunner = async (cwd, cmd, timeoutMs) => {
120	  const p = Bun.spawn(["bash", "-c", cmd], { cwd, env: gitEnv(), stdout: "ignore", stderr: "ignore", timeout: timeoutMs });
121	  return (await p.exited) === 0;
122	};
123	
124	function hasTypecheck(dir: string): boolean {
125	  try {
126	    return typeof JSON.parse(readFileSync(join(dir, "package.json"), "utf8")).scripts?.typecheck === "string";
127	  } catch {
128	    return false;
129	  }
130	}
131	
132	function showOrNull(cwd: string, rev: string, path: string): string | null {
133	  const r = Bun.spawnSync(["git", "show", `${rev}:${path}`], { cwd });
134	  return r.exitCode === 0 ? r.stdout.toString() : null;
135	}
136	
137	// macOS tar packs extended attributes and AppleDouble files by default; a file whose xattrs vanish mid-read makes the
138	// producer fail, and without pipefail the half-written copy went unnoticed (missing .git objects, "bad object" later).
139	const TAR_FLAGS = process.platform === "darwin" ? "--no-xattrs --no-mac-metadata " : "";
140	const COPY_CMD = `set -o pipefail; tar ${TAR_FLAGS}-C "$1" --exclude=./node_modules --exclude=./web/node_modules -cf - . | tar ${TAR_FLAGS}-C "$2" -xf -`;
141	
142	/** Copies `from` into the empty directory `to` (without node_modules), retrying once from scratch. */
143	export function copyTree(from: string, to: string): void {
144	  let err = "";
145	  for (let attempt = 1; attempt <= 2; attempt++) {
146	    rmSync(to, { recursive: true, force: true });
147	    mkdirSync(to, { recursive: true });
148	    const cp = Bun.spawnSync(["bash", "-c", COPY_CMD, "bash", from, to], { env: { ...gitEnv(), COPYFILE_DISABLE: "1" } });
149	    if (cp.exitCode === 0) return;
150	    err = cp.stderr.toString().trim();
151	  }
152	  throw new Error(`copy failed: ${err}`);
153	}
154	
155	/** A suite with more failing files than this failed for real, not on timing: no retry. */
156	const SUITE_RETRY_MAX_FILES = 5;
157	
158	/** Grade a finished replay in a fresh copy: base + the agent's patch (+ hidden tests for the second run). */
159	export async function grade(input: GradeInput): Promise<GradeResult> {
160	  const { sandbox, hidden, preexistingTests } = input;
161	  const timeout = input.timeoutMs ?? 300_000;
162	  const phase = input.phase ?? "all";
163	  const run = input.runner ?? sh;
164	  const root = mkdtempSync(join(tmpdir(), "roster-grade-"));
165	  const work = join(root, "work");
166	  const out = join(root, "junit"); // JUnit lives outside the workspace
167	  mkdirSync(out);
168	  try {
169	    // node_modules is the bulk of the copy and is cleaned out below anyway: leave it behind and link it back in.
170	    copyTree(sandbox.path, work);
171	
172	    // Capture the agent's change as a patch, then rebuild the tree from base + patch.
173	    runGit(work, ["add", "-A"]);
174	    const patch = runGit(work, ["diff", "--cached", "--binary", sandbox.baseSha]);
175	    const changed = runGit(work, ["diff", "--cached", "--name-only", "-z", sandbox.baseSha]).split("\0").filter(Boolean);
176	    const patchedText = (p: string) => showOrNull(work, ":0", p);
177	    const violations: Violation[] = [
178	      ...testEditViolations(preexistingTests, (p) => showOrNull(work, sandbox.baseSha, p), patchedText),
179	      ...(input.touchedDirs ? offScopeViolations(changed, input.touchedDirs) : []),
180	    ];
181	    runGit(work, ["reset", "-q", "--hard", sandbox.baseSha]);
182	    runGit(work, ["clean", "-qfdx"]);
183	    if (patch) {
184	      const pf = join(out, "agent.patch");
185	      writeFileSync(pf, patch + "\n");
186	      runGit(work, ["apply", "--binary", pf]);
187	    }
188	
189	    const modulesFrom = input.modulesFrom ?? sandbox.path;
190	    for (const rel of ["node_modules", "web/node_modules"]) {
191	      const src = join(modulesFrom, rel);
192	      if (!existsSync(src)) continue;
193	      mkdirSync(dirname(join(work, rel)), { recursive: true });
194	      symlinkSync(src, join(work, rel), "dir");
195	    }
196	
197	    const testCmd = input.testCmd ?? detectTestCmd(work);
198	    const isBun = /^bun test\b/.test(testCmd);
199	    const junit = (name: string) => (isBun ? ` --reporter=junit --reporter-outfile=${join(out, name)}` : "");
200	    const scopeOk = violations.length === 0;
201	
202	    let suitePass: boolean | null = null;
203	    let suiteFailing: string[] | null | undefined;
204	    if (phase !== "fast") {
205	      suitePass = await run(work, testCmd + junit("suite.xml"), timeout, "suite");
206	      // A loaded machine fails the odd test on timing: re-run only the failing files, once. A run that left no JUnit
207	      // (killed, crashed, import errors bun drops) has nothing to retry and stays failed.
208	      const xml = join(out, "suite.xml");
209	      const retryXml = join(out, "suite-retry.xml");
210	      if (!suitePass && isBun && existsSync(xml)) {
211	        const failing = failingTestFiles(readFileSync(xml, "utf8"));
212	        suiteFailing = failing;
213	        if (failing.length > 0 && failing.length <= SUITE_RETRY_MAX_FILES) {
214	          suitePass = await run(work, `${testCmd} ${failing.map((f) => JSON.stringify(f)).join(" ")}${junit("suite-retry.xml")}`, timeout, "retry");
215	          if (!suitePass) suiteFailing = existsSync(retryXml) ? failingTestFiles(readFileSync(retryXml, "utf8")) : null;
216	        }
217	      } else if (!suitePass) suiteFailing = null;
218	      if (suitePass) suiteFailing = undefined;
219	    }
220	    if (phase === "suite") return { hiddenPass: true, suitePass, suiteFailing, typecheckPass: null, scopeOk, violations, perTest: [] };
221	
222	    const fileArgs = isBun || /^pytest\b/.test(testCmd);
223	    // In the fast phase the change's own new test files run separately from the hidden ones.
224	    const own =phase === "fast" && fileArgs ? changed.filter((p) => isTestFile(p) && !preexistingTests.includes(p) && !hidden.some((h) => h.path === p) && existsSync(join(work, p))) : [];
225	    for (const h of hidden) {
226	      mkdirSync(dirname(join(work, h.path)), { recursive: true });
227	      writeFileSync(join(work, h.path), h.content);
228	    }
229	    const files = hidden.map((h) => JSON.stringify(h.path)).join(" ");
230	    const skipRun = phase === "fast" && fileArgs && files === "";
231	    const runPass = skipRun || (await run(work, `${testCmd}${fileArgs ? " " + files : ""}${junit("hidden.xml")}`, timeout, "hidden"));
232	    const ownPass: boolean | null = own.length ? await run(work, `${testCmd} ${own.map((p) => JSON.stringify(p)).join(" ")}${junit("own.xml")}`, timeout, "own") : null;
233	
234	    let typecheckPass: boolean | null = null;
235	    if (phase === "fast" && isBun && hasTypecheck(work)) typecheckPass = await run(work, "bun run typecheck", timeout, "typecheck");
236	
237	    let perTest: PerTest[] = [];
238	    let hiddenPass = runPass;
239	    const xmlPath = join(out, "hidden.xml");
240	    if (isBun) {
241	      const all = existsSync(xmlPath) ? parseJunit(readFileSync(xmlPath, "utf8")) : [];
242	      const norm = (f: string) => f.replace(/^\.\//, "");
243	      for (const h of hidden) {
244	        const cases = all.filter((t) => norm(t.file).endsWith(h.path) || h.path.endsWith(norm(t.file)));
245	        if (cases.length === 0) {
246	          // bun's JUnit reporter drops files that fail to import: count it as a failure.
247	          perTest.push({ file: h.path, name: "(collected 0 tests)", pass: false });
248	        } else perTest.push(...cases.map((c) => ({ ...c, file: h.path })));
249	      }
250	      hiddenPass = runPass && perTest.every((t) => t.pass);
251	    } else if (hidden.length === 0) hiddenPass = true;
252	
253	    return { hiddenPass, suitePass, suiteFailing, typecheckPass, ownPass, scopeOk, violations, perTest };
254	  } finally {
255	    rmSync(root, { recursive: true, force: true });
256	  }
257	}
