// The blind diff-judge (DESIGN.md §"Grade" step 5 and §"Forward run"): both diffs go to the judge under a seeded
// X/Y coin flip, with every setup id scrubbed out, and the reply is read back as the setup id it names.
import { rng } from "../forward/blind.ts";

/** One side of a pair: what wrote the diff, and the diff itself. */
export interface JudgeInput {
  setup: string;
  diff: string;
}

export interface BlindPair {
  /** The judge's whole input: both diffs, labelled, with nothing that identifies a setup. */
  prompt: string;
  /** Which setup each label stands for, so a verdict can be mapped back. */
  labels: Record<"X" | "Y", string>;
}

/** Hides a setup id (and the branch pattern a diff header tends to carry) behind a neutral placeholder. */
function hideSetup(text: string, setups: string[]): string {
  let out = text.replace(/forward\/[\w.-]+\/(old|new)/g, "<branch>");
  for (const s of setups) if (s.length > 0) out = out.split(s).join("<setup>");
  return out;
}

const RULES = [
