// The blind diff-judge (DESIGN.md §"Grade" step 5 and §"Forward run"): both diffs go to the judge under a seeded X/Y
// coin flip with every setup id scrubbed out, and the reply is read back as the setup id it names. The judge is
// advisory; the point here is only that it cannot tell which setup wrote which diff, and that a malformed reply is
// "unclear" rather than a silent pick.
import { rng } from "../forward/blind.ts";

/** One side of the pair: what wrote the diff, and the diff itself. */
export interface JudgeInput {
  setup: string;
  diff: string;
}

export interface BlindPair {
  /** The judge's whole input: both diffs, labelled, with nothing that identifies a setup. */
  prompt: string;
  /** Which setup each label stands for, so a verdict can be mapped back. */
  labels: Record<"X" | "Y", string>;
}

export interface Verdict {
  /** The setup the judge picked, or "tie" / "unclear" when it named neither. */
  winner: string | "tie" | "unclear";
}

const RULES = [
  "You compare two candidate changes, X and Y, for the same task.",
  "You know nothing about who or what wrote them: judge only what you can see.",
  "Prefer correctness against the task, then scope discipline, then simplicity, then a smaller change.",
  'End your reply with exactly one final line: "VERDICT: X", "VERDICT: Y" or "VERDICT: TIE".',
].join(" ");

/** Replaces a setup id, and the branch name a diff header tends to carry, with a neutral placeholder. */
function hide(text: string, setups: string[]): string {
  let out = text.replace(/forward\/[\w.-]+\/(old|new)/g, "<branch>");
  for (const s of setups) if (s.length > 0) out = out.split(s).join("<setup>");
  return out;
}

/** Labels the two diffs X and Y by a seeded coin flip and writes the judge's prompt. Nothing names a setup. */
export function blindPair(a: JudgeInput, b: JudgeInput, seed: number): BlindPair {
  const x = rng(seed)() < 0.5 ? a : b;
  const y = x === a ? b : a;
  const setups = [a.setup, b.setup];
  const prompt = [
    RULES,
    "",
    "=== Change X ===",
    hide(x.diff, setups),
    "",
    "=== Change Y ===",
    hide(y.diff, setups),
    "",
  ].join("\n");
  return { prompt, labels: { X: x.setup, Y: y.setup } };
}

// "verdict:" then a word. Wrapping (`**VERDICT: Y**`) and trailing punctuation fall outside the word, so they are
// tolerated; a word that is not X, Y or TIE is not.
const VERDICT_LINE = /verdict\s*:\s*(\w*)/gi;

/** Reads the last "VERDICT: X|Y|TIE" line and maps it back to a setup id; anything else is "unclear". */
export function parseVerdict(text: string | null, labels: Record<"X" | "Y", string>): Verdict {
  const last = [...(text ?? "").matchAll(VERDICT_LINE)].at(-1);
  const token = (last?.[1] ?? "").toUpperCase();
  if (token === "TIE") return { winner: "tie" };
  if (token === "X") return { winner: labels.X };
  if (token === "Y") return { winner: labels.Y };
  return { winner: "unclear" };
}

